"""Test-only injection around the unmodified d7a initialization control flow."""

def once(text, old, new):
    if text.count(old) != 1:
        raise ValueError("unexpected source layout: " + old[:80])
    return text.replace(old, new, 1)

def instrument(source):
    text = source.read_text()
    text = once(text, 'VkEmulation* createGlobalVkEmulation(VulkanDispatch* vk, gfxstream::host::FeatureSet features) {', 'static int auditSelectionMode = -1;\nstatic int auditSelectionValue = -200;\nstatic VKAPI_ATTR void VKAPI_CALL auditQueueProperties(VkPhysicalDevice, uint32_t* count, VkQueueFamilyProperties* properties) {\n    const uint32_t n = (auditSelectionMode == 6 || auditSelectionMode == 7) ? 2 : 1;\n    if (!properties) { *count = n; return; }\n    if (*count < n) return;\n    memset(properties, 0, n * sizeof(*properties));\n    properties[0].queueCount = auditSelectionMode == 8 ? 0 : 1;\n    properties[0].queueFlags = VK_QUEUE_GRAPHICS_BIT;\n    if (auditSelectionMode != 5 && auditSelectionMode != 6 && auditSelectionMode != 7)\n        properties[0].queueFlags |= VK_QUEUE_COMPUTE_BIT;\n    if (n == 2) {\n        properties[1].queueCount = 1;\n        properties[1].queueFlags = VK_QUEUE_COMPUTE_BIT;\n        if (auditSelectionMode == 7) properties[1].queueFlags |= VK_QUEUE_GRAPHICS_BIT;\n    }\n    *count = n;\n}\n' + 'VkEmulation* createGlobalVkEmulation(VulkanDispatch* vk, gfxstream::host::FeatureSet features) {')
    text = once(text, '    uint32_t physdevCount = 0;', '    if (auditSelectionMode >= 0) ivk->vkGetPhysicalDeviceQueueFamilyProperties = auditQueueProperties;\n' + '    uint32_t physdevCount = 0;')
    text = once(text, '    std::vector<uint32_t> deviceScores(physdevCount, 0);', '    if (auditSelectionMode >= 0) {\n        auto base = deviceInfos.at(0);\n        fprintf(stderr, "AUDIT_BACKING=%s type=%d\\n", base.physdevProps.deviceName, base.physdevProps.deviceType);\n        base.physdevProps.apiVersion = VK_API_VERSION_1_2;\n        base.physdevProps.deviceType = VK_PHYSICAL_DEVICE_TYPE_CPU;\n        deviceInfos = {base};\n        if (auditSelectionMode == 1) deviceInfos[0].physdevProps.deviceType = VK_PHYSICAL_DEVICE_TYPE_VIRTUAL_GPU;\n        if (auditSelectionMode == 2 || auditSelectionMode == 3 || auditSelectionMode == 9) {\n            deviceInfos[0].physdevProps.deviceType = VK_PHYSICAL_DEVICE_TYPE_VIRTUAL_GPU;\n            auto gpu = base; gpu.physdevProps.deviceType = VK_PHYSICAL_DEVICE_TYPE_INTEGRATED_GPU;\n            if (auditSelectionMode == 9) deviceInfos[0].physdevProps.deviceType = VK_PHYSICAL_DEVICE_TYPE_DISCRETE_GPU;\n            deviceInfos.push_back(gpu);\n            physdevs.push_back(physdevs[0]);\n        }\n        if (auditSelectionMode >= 4 && auditSelectionMode <= 8) deviceInfos[0].physdevProps.deviceType = VK_PHYSICAL_DEVICE_TYPE_INTEGRATED_GPU;\n        if (auditSelectionMode == 4) deviceInfos[0].physdevProps.apiVersion = VK_API_VERSION_1_1;\n        if (auditSelectionMode == 10) { deviceInfos[0].physdevProps.deviceType = VK_PHYSICAL_DEVICE_TYPE_INTEGRATED_GPU; deviceInfos[0].physdevProps.apiVersion = VK_MAKE_API_VERSION(1, 1, 2, 0); }\n        physdevCount = deviceInfos.size();\n        if (auditSelectionMode == 3) sVkEmulation->instanceSupportsExternalMemoryCapabilities = false;\n        auditSelectionValue = -1;\n    }\n' + '    std::vector<uint32_t> deviceScores(physdevCount, 0);')
    text = once(text, '    std::unordered_set<const char*> selectedDeviceExtensionNames_;', '    if (auditSelectionMode >= 0) {\n        auditSelectionValue = 100 * static_cast<int>(sVkEmulation->physicalDeviceIndex) + dqCi.queueFamilyIndex;\n        return nullptr;\n    }\n' + '    std::unordered_set<const char*> selectedDeviceExtensionNames_;')
    text = once(text, 'VkEmulation* getGlobalVkEmulation() {', 'extern "C" __attribute__((visibility("default"))) int rme_audit_device_selection(int mode) {\n    auditSelectionMode = mode;\n    auditSelectionValue = -200;\n    createGlobalVkEmulation(vkDispatch(false), gfxstream::host::FeatureSet{});\n    return auditSelectionValue;\n}\n' + 'VkEmulation* getGlobalVkEmulation() {')
    source.write_text(text)
